<?php declare(strict_types=1);
use Kulturhus\Verein\Settings\RoleDraft;
$roleStaleReview=$roleDraft['review']&&array_intersect(RoleDraft::issues($roleDraft['review']),['Die ursprüngliche Fassung ist nicht mehr aktuell.','Die ursprüngliche persönliche Zuordnung ist nicht mehr aktuell.']);
$di=$roleDraft['input'];$draftId=$roleDraft['id'];$isRole=$roleOperation==='role-save';$roleFormHeading=$roleTitles[$roleOperation];
$roleHidden=static fn():string=>csrf().hidden('action','role-native').hidden('role_draft',$draftId);
$roleChoice=static function(array $listing,string $name,string $label,array $special)use($rt,$rf,$roleField,$roleSelect):void{
    $prefix=$listing['prefix'];$options=[];foreach($special as$key=>$source)$options[$key]=$rt($source);foreach($listing['rows']as$row)$options[$row['id']]=$row['name'];if($listing['selected'])$options[$listing['selected']['id']]=$listing['selected']['name'];
    ?><fieldset class="role-choice"><legend><?= e($rt($label)) ?></legend><?php $roleField('role_choice['.$prefix.'_q]','Suche',$listing['query']);$roleField('role_choice['.$prefix.'_page]','Auswahlseite',$listing['page_input']); ?><button class="btn btn-outline theme-secondary" name="role_intent" value="browse"><?= e($rt('Auswahl anzeigen')) ?></button><?php if($listing['error']!==''): ?><p role="alert"><?= e($rt($listing['error'])) ?></p><?php endif ?><?php if($listing['total']!==null): ?><p><?= e($rf('{count} passende Einträge · höchstens sechs Vorschläge',['count'=>$listing['total']])) ?></p><?php endif ?><?php if($listing['pages']!==null): ?><p><?= e($rf('Seite {page} von {pages}',['page'=>$listing['page_input'],'pages'=>$listing['pages']])) ?></p><?php endif ?><?php if($listing['unavailable']): ?><p role="alert"><?= e($rt('Gewählte Zuordnung nicht verfügbar')) ?></p><?php endif ?><?php $roleSelect($name,$label,$options,$listing['selection']); ?></fieldset><?php
};
?>
<section class="card role-native-compose" id="<?= $isRole?'role-edit':'role-compose-'.$draftId ?>" data-role-compose="<?= e($roleOperation) ?>" data-role-draft="<?= e($draftId) ?>">
<h2><?= e($rt($roleFormHeading)) ?></h2>
<?php if($roleDraft['accepted']!==null): ?><p><?= e($rt('Diese Änderung wurde angenommen.')) ?></p><a class="btn btn-outline theme-secondary" href="<?= e($ru(['role_receipt'=>$roleDraft['key']])) ?>#role-original"><?= e($rt('Änderung ansehen')) ?></a>
<?php else: ?>
<?php if($roleDraft['conflicted']??false): ?><p role="alert"><?= e($rt('Die Änderung wurde abgewiesen. Den Entwurf korrigieren oder mit aktuellem Stand neu prüfen.')) ?></p><?php endif ?>
<?php if($roleDraft['pending']): ?><p role="alert"><?= e($rt('Der Speicherstatus ist noch offen. Bitte den Änderungsverlauf prüfen.')) ?></p><a class="btn btn-outline theme-secondary" data-role-check href="<?= e($ru(['role_draft'=>$draftId,'role_receipt'=>$roleDraft['key']])) ?>#role-original"><?= e($rt('Speicherstatus prüfen')) ?></a><?php endif ?>
<details class="role-technical-details"><summary><?= e($rt('Technische Details')) ?></summary><p class="role-proof"><?= e($rt('Ursprüngliche Änderungskennung')) ?>: <?= e($roleDraft['key']) ?></p>
<?php if(!$roleDraft['pending']): ?><a class="btn btn-outline theme-secondary" data-role-check href="<?= e($ru(['role_draft'=>$draftId,'role_receipt'=>$roleDraft['key']])) ?>#role-original"><?= e($rt('Änderung ansehen')) ?></a><?php endif ?></details>
<form method="post" class="role-native-form" data-native-role-editor><?= $roleHidden() ?>
<?php foreach($di as$field=>$value)if(!in_array($field,['data','role','contact','office','enabled'],true))echo hidden('role_input['.$field.']',$scalar($value)); ?>
<?php if($isRole):$data=is_array($di['data']??null)?$di['data']:[]; ?>
<div class="form-grid"><?php $roleField('role_input[data][name]','Rollenname',$data['name']??'');$roleField('role_input[data][description]','Beschreibung',$data['description']??'',true); ?></div><p><?= e($rt('Rollenname: höchstens 100 Zeichen. Beschreibung: höchstens 1.000 Zeichen.')) ?></p>
<div class="role-native-rights"><?php foreach($roleRights as$field=>$label)$roleSelect('role_input[data]['.$field.']',$label,$roleLevels,$data[$field]??'',true);$roleSelect('role_input[data][settings_access]','Vereinseinstellungen und Rollen verwalten',['0'=>'Nein','1'=>'Ja'],$data['settings_access']??'',true); ?></div>
<p><?= e($rt('Wer Rollen verwaltet, kann Rechte vergeben. Mindestens ein aktiver Zugang muss diese Berechtigung behalten. Lesen erlaubt keine Änderungen.')) ?></p>
<?php $roleSelect('role_input[data][website_custom]','Eigene Website-Bereichsfreigaben',['0'=>'Voreinstellungen verwenden','1'=>'Eigene Freigaben verwenden'],$data['website_custom']??'',true); ?>
<p><?= e($rt('Website-Voreinstellungen folgen dieser Vereinsrolle. Redaktion und Superuser können zusätzliche Grundrechte behalten. Tatsächlich nutzbare Rechte stehen beim jeweiligen Konto.')) ?></p>
<div class="role-native-rights"><?php foreach(\Kulturhus\Verein\EditorialPolicy::AREAS as$area=>$label)$roleSelect('role_input[data][website_levels]['.$area.']',$label,$roleLevels,$data['website_levels'][$area]??'',true); ?></div>
<button class="btn btn-outline theme-secondary" name="role_intent" value="defaults"><?= e($rt('Website-Voreinstellungen einsetzen')) ?></button>
<p role="status" data-native-role-status data-custom="<?= e($rt('Eigene Website-Freigaben sind gewählt. Die vollständige Änderung zuerst prüfen.')) ?>" data-default="<?= e($rt('Voreinstellungen sind gewählt. Einzelne Website-Auswahlen werden dabei nicht übernommen.')) ?>"></p>
<?php elseif($roleOperation==='role-assign'):$roleChoice($roleDraft['role_choices'],'role_input[role]','Vereinsrolle',[''=>'Vereinsrolle auswählen','__base__'=>'Nur Grundrolle verwenden']); ?>
<?php elseif($roleOperation==='board-grant'): ?><p><?= e($rt('Persönliches Vorstandsamt und bestätigtes Stimmrecht sind von der Vereinsrolle und technischen Administration getrennt.')) ?></p><?php $roleSelect('role_input[office]','Vorstandsamt',[''=>'Kein Vorstandsamt']+array_combine(\Kulturhus\Verein\AdmissionVotes::OFFICES,\Kulturhus\Verein\AdmissionVotes::OFFICES),$di['office']??'',true);$roleSelect('role_input[enabled]','Persönliches Stimmrecht bestätigen',['0'=>'Nein','1'=>'Ja'],$di['enabled']??'',true); ?>
<?php elseif($roleOperation==='identity-assign'): ?><p><?= e($rt('Eine geänderte persönliche Profilzuordnung wird separat geprüft. Eine Sperre erhält gespeicherte Rollen und Vorstandsämter. Bei erneuter Freigabe können diese wieder gelten.')) ?></p><?php $roleChoice($roleDraft['role_choices'],'role_input[role]','Vereinsrolle',['__keep__'=>'Bisherige Vereinsrolle beibehalten','__base__'=>'Nur Grundrolle verwenden']);$roleChoice($roleDraft['profile_choices'],'role_input[contact]','Eigenes Mitgliederprofil',[''=>'Keine Profilverknüpfung']);$roleSelect('role_input[enabled]','Zugang erlauben',['0'=>'Nein','1'=>'Ja'],$di['enabled']??'',true); ?>
<?php else: ?><p><?= e($rt('Technische Konten- und Systemrechte vergeben keine persönliche Vorstandsstimme.')) ?></p><?php $roleSelect('role_input[enabled]','Technische Administration für Website und Vereinsmanager',['0'=>'Nein','1'=>'Ja'],$di['enabled']??'',true);endif ?>
<div class="settings-actions"><button class="btn btn-solid theme-primary" name="role_intent" value="preview"<?= $roleDraft['pending']?' disabled':'' ?>><?= e($rt('Änderung prüfen')) ?></button><?php if(($roleDraft['conflicted']??false)||$roleStaleReview): ?><button class="btn btn-outline theme-secondary" name="role_intent" value="current"><?= e($rt('Aktuellen Stand laden')) ?></button><?php endif ?><button class="btn btn-outline theme-secondary" name="role_intent" value="discard"<?= $roleDraft['pending']?' disabled':'' ?>><?= e($rt('Entwurf verwerfen')) ?></button></div></form>
<?php if($roleDraft['review']): ?><section class="role-review" data-role-review><h3><?= e($rt('Geprüfte Änderung')) ?></h3><?php $roleDescribe($roleOperation,$roleDraft['review']['input']);$roleContext($roleDraft['review']['context']);foreach(RoleDraft::issues($roleDraft['review'])as$issue): ?><p role="alert"><?= e($rt($issue)) ?></p><?php endforeach ?>
<?php if(!RoleDraft::issues($roleDraft['review'])&&!$roleDraft['pending']&&!($roleDraft['conflicted']??false)): ?><form method="post" data-role-accept><?= $roleHidden().hidden('role_review',$roleDraft['review']['hash']).hidden('role_key',$roleDraft['key']) ?><label class="role-approval"><input type="checkbox" name="role_approved" value="1" required><?= e($rt('Diese vollständig geprüfte Änderung ausdrücklich bestätigen')) ?></label><button class="btn btn-solid theme-primary" name="role_intent" value="accept"><?= e($rt('Geprüfte Änderung speichern')) ?></button></form><?php endif ?></section><?php endif ?>
<?php if($roleDraft['previous']): ?><details data-role-previous><summary><?= e($rt('Frühere vorgeschlagene Angaben')) ?></summary><?php foreach($roleDraft['previous']as$prior): ?><article><p class="role-proof"><?= e($prior['key']) ?></p><?php $roleDescribe($roleOperation,$prior['input']);if($prior['review'])$roleContext($prior['review']['context']); ?></article><?php endforeach ?></details><?php endif ?>
<?php endif ?></section>
